(7579394, 1218517, 87808, '<td valign="top">I feel like some contrast would work well here, it is slightly flat, everything is the same shades.</td>', 'I feel like some contrast would work well here, it is slightly flat, everything is the same shades.', '2018-07-09 01:45:33.000000', NULL, 1),
(7579397, 1218521, 87808, '<td valign="top">I relly like this, but feel that if a lower angle would help it. you have the smoothness of the waters, but then the sharpness of the sky and buildings maybe if shot t half the angle you are at now, it would all be cohesive. But then again, I am no expert.</td>', 'I relly like this, but feel that if a lower angle would help it. you have the smoothness of the waters, but then the sharpness of the sky and buildings maybe if shot t half the angle you are at now, it would all be cohesive. But then again, I am no expert.', '2018-07-09 01:49:13.000000', NULL, 1),
(7579398, 1218989, 87808, '<td valign="top">To me, if you had turned this black and white, with a little structure to the clouds, this would be a 10.</td>', 'To me, if you had turned this black and white, with a little structure to the clouds, this would be a 10.', '2018-07-09 01:50:27.000000', NULL, 1),
(7579414, 1218267, 87808, '<td valign="top">That duck, makes the whole picture worth a 9. If that was not there, then it would just be fairly normal blah. but pretty picture, but you have go the duck. Well done!</td>', 'That duck, makes the whole picture worth a 9. If that was not there, then it would just be fairly normal blah. but pretty picture, but you have go the duck. Well done!', '2018-07-09 02:11:47.000000', NULL, 1),
(7579416, 1218267, 96751, '<td valign="top">Yeah, that goose makes the shot. Perhaps a bit too much glow...</td>', 'Yeah, that goose makes the shot. Perhaps a bit too much glow...', '2018-07-09 02:13:13.000000', NULL, 1),
(7579417, 1218423, 96751, '<td valign="top">A beautiful view for sure, but as much as I want to love this, the pp''g is a bit overly aggressive for me.</td>', 'A beautiful view for sure, but as much as I want to love this, the pp''g is a bit overly aggressive for me.', '2018-07-09 02:15:48.000000', NULL, 1),
